    $vals=[];foreach($fields as $f){$vals[$f]=$d[$f]??null;if($vals[$f]==='')$vals[$f]=null;}$vals['geracao_meses']=json_encode($ger);$vals['consumo_meses']=json_encode($con);$vals['usuario_id']=$_SESSION['usuario_id'];
    if($id){$set=implode(', ',array_map(fn($f)=>"$f=:$f",array_keys($vals)));$vals['id']=$id;$db->prepare("UPDATE propostas SET $set WHERE id=:id")->execute($vals);$pid=$id;$db->prepare('DELETE FROM proposta_itens WHERE proposta_id=?')->execute([$pid]);}
    else{$numero='PROP'.date('Ymd').str_pad((int)$db->query('SELECT COUNT(*)+1 FROM propostas')->fetchColumn(),4,'0',STR_PAD_LEFT);$vals['numero']=$numero;$cols=implode(',',array_keys($vals));$ph=implode(',',array_map(fn($f)=>":$f",array_keys($vals)));$db->prepare("INSERT INTO propostas ($cols) VALUES ($ph)")->execute($vals);$pid=(int)$db->lastInsertId();}
    $desc=$d['item_descricao']??[];foreach($desc as $i=>$texto){$texto=trim($texto);if($texto==='')continue;$produto=($d['item_produto'][$i]??'')?:null;$q=(float)($d['item_quantidade'][$i]??1);$u=$d['item_unidade'][$i]??'un';$preco=(float)($d['item_preco'][$i]??0);$total=$q*$preco;$db->prepare('INSERT INTO proposta_itens(proposta_id,produto_id,descricao,quantidade,unidade,preco_unitario,total,ordem) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,$produto,$texto,$q,$u,$preco,$total,$i]);}
    $db->commit();$_SESSION['msg']=$id?'Proposta atualizada com sucesso!':'Proposta criada com sucesso!';header('Location:view.php?id='.$pid);exit;
  }catch(Throwable $e){$db->rollBack();$erro='Não foi possível salvar: '.$e->getMessage();}
}
