ss="form-row cols-4"><div class="form-group"><label>Tipo de conexão</label><select name="tipo_conexao"><?php foreach(['Monofásico','Bifásico','Trifásico'] as $x):?><option <?= ($v['tipo_conexao']??'Monofásico')===$x?'selected':'' ?>><?= $x ?></option><?php endforeach;?></select></div><div class="form-group"><label>Tensão da rede</label><select name="tensao_rede"><?php foreach(['127/220','220/380','220','380'] as $x):?><option <?= ($v['tensao_rede']??'127/220')===$x?'selected':'' ?>><?= $x ?> V</option><?php endforeach;?></select></div><div class="form-group"><label><input type="checkbox" name="inclui_iluminacao" value="1" <?= !empty($v['inclui_iluminacao'])?'checked':'' ?>> Incluir iluminação pública</label></div><div class="form-group"><label>Valor da iluminação (R$)</label><input type="number" step="0.01" name="valor_iluminacao" value="<?= htmlspecialchars($v['valor_iluminacao']??0) ?>"></div></div></div></div></div>
