p"><label>Geração anual (kWh)</label><input id="geracaoAnual" type="number" step="0.01" name="geracao_anual_kwh" value="<?= htmlspecialchars($v['geracao_anual_kwh']??'') ?>"></div><div class="form-group"><label>Geração média mensal (kWh)</label><input id="geracaoMensal" type="number" step="0.01" name="geracao_mensal_kwh" value="<?= htmlspecialchars($v['geracao_mensal_kwh']??'') ?>"></div></div></div></div>
