<template id="itemTpl"><tr><td><select name="item_produto[]" onchange="produtoSelecionado(this)"><option value="">Livre</option><?php foreach($produtos as $pr):?><option value="<?= $pr['id'] ?>" data-nome="<?= htmlspecialchars($pr['nome']) ?>" data-unidade="<?= htmlspecialchars($pr['unidade']) ?>" data-preco="<?= (float)$pr['preco_venda'] ?>"><?= htmlspecialchars($pr['codigo'].' '.$pr['nome']) ?></option><?php endforeach;?></select></td><td><input name="item_descricao[]" required></td><td><input class="item-qtd" type="number" step="0.01" name="item_quantidade[]" value="1" oninput="calcular()"></td><td><input class="item-un" name="item_unidade[]" value="un"></td><td><input class="item-preco" type="number" step="0.01" name="item_preco[]" value="0" oninput="calcular()"></td><td class="item-total">R$ 0,00</td><td><button type="button" class="btn btn-danger btn-sm btn-icon" onclick="this.closest('tr').remove();calcular()"><i class="fa-solid fa-trash"></i></button></td></tr></template>
<script>
const money=v=>'R$ '+Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
function addItem(){document.querySelector('#itens tbody').append(document.getElementById('itemTpl').content.cloneNode(true));}
function produtoSelecionado(s){const o=s.selectedOptions[0],tr=s.closest('tr');if(!o.value)return;tr.querySelector('[name="item_descricao[]"]').value=o.dataset.nome;tr.querySelector('.item-un').value=o.dataset.unidade;tr.querySelector('.item-preco').value=o.dataset.preco;calcular();}
function calcular(){let soma=0;document.querySelectorAll('#itens tbody tr').forEach(tr=>{let t=(parseFloat(tr.querySelector('.item-qtd').value)||0)*(parseFloat(tr.querySelector('.item-preco').value)||0);tr.querySelector('.item-total').textContent=money(t);soma+=t;});document.getElementById('equipamentos').value=soma.toFixed(2);calcularResumo();}
function calcularResumo(){const equipamentos=document.getElementById('equipamentos'),servicos=document.getElementById('servicos'),desconto=document.getElementById('desconto'),valorTotal=document.getElementById('valorTotal'),entrada=document.getElementById('entrada'),saldo=document.getElementById('saldo');let total=(parseFloat(equipamentos.value)||0)+(parseFloat(servicos.value)||0)-(parseFloat(desconto.value)||0);valorTotal.value=Math.max(0,total).toFixed(2);saldo.value=Math.max(0,total-(parseFloat(entrada.value)||0)).toFixed(2);}
function preencherMeses(){let g=parseFloat(document.getElementById('geracaoMensal').value)||0,c=parseFloat(document.getElementById('consumoMensal').value)||0;document.querySelectorAll('[name^="geracao_"]').forEach(i=>{if(!['geracao_anual_kwh','geracao_mensal_kwh'].includes(i.name))i.value=g.toFixed(2)});document.querySelectorAll('[name^="consumo_"]').forEach(i=>i.value=c.toFixed(2));}
function atualizarEstimativa(){const c=parseFloat(document.getElementById('consumoMensal').value)||0,h=parseFloat(document.getElementById('hsp').value)||0,e=(parseFloat(document.getElementById('eficiencia').value)||80)/100;const p=h&&e?c/(h*30*e):0;document.getElementById('hspResultado').textContent=h.toLocaleString('pt-BR',{minimumFractionDigits:2})+' kWh/m²';document.getElementById('potenciaResultado').textContent=p.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' kWp';const q=[document.getElementById('cidade').value,document.getElementById('estado').value].filter(Boolean).join(', ');document.getElementById('mapLink').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q||document.getElementById('localidade').value);return p;}
function dimensionar(){const p=atualizarEstimativa(),wp=parseFloat(document.getElementById('painelWp').value)||550,kwp=Math.ceil((p*1000)/wp)*wp/1000,q=Math.max(1,Math.ceil((p*1000)/wp)),h=parseFloat(document.getElementById('hsp').value)||0,e=(parseFloat(document.getElementById('eficiencia').value)||80)/100,g=kwp*h*30*e;document.getElementById('potenciaKwp').value=kwp.toFixed(2);document.getElementById('qtdModulos').value=q;document.getElementById('areaM2').value=(q*2.2).toFixed(2);document.getElementById('geracaoMensal').value=g.toFixed(2);document.getElementById('geracaoAnual').value=(g*12).toFixed(2);}
document.getElementById('cliente').addEventListener('change',function(){const o=this.selectedOptions[0],localidade=document.getElementById('localidade'),estrutura=document.getElementById('estrutura');if(!localidade.value)localidade.value=o.dataset.local||'';if(!estrutura.value)estrutura.value=(o.dataset.estrutura||'').replace('_',' ');document.getElementById('cidade').value=o.dataset.cidade||'';document.getElementById('estado').value=o.dataset.estado||'';if(!document.getElementById('consumoMensal').value)document.getElementById('consumoMensal').value=o.dataset.consumo||'';document.getElementById('clienteResumo').textContent=o.value?`${o.dataset.nome} • ${o.dataset.local||'Local não informado'} • Consumo cadastrado: ${o.dataset.consumo||0} kWh/mês`:'Selecione um cliente.';atualizarEstimativa();});
['consumoMensal','hsp','eficiencia','cidade','estado'].forEach(id=>document.getElementById(id).addEventListener('input',atualizarEstimativa));
let passo=1;function mostrarPasso(n){passo=Math.max(1,Math.min(5,n));document.querySelectorAll('.wizard-pane').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===passo));document.querySelectorAll('.proposal-steps button').forEach(x=>x.classList.toggle('active',Number(x.dataset.go)===passo));document.getElementById('btnAnterior').style.visibility=passo===1?'hidden':'visible';document.getElementById('btnProximo').style.display=passo===5?'none':'inline-flex';document.getElementById('btnSalvar').style.display=passo===5?'inline-flex':'none';window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('.proposal-steps button').forEach(b=>b.addEventListener('click',()=>mostrarPasso(Number(b.dataset.go))));document.getElementById('btnAnterior').addEventListener('click',()=>mostrarPasso(passo-1));document.getElementById('btnProximo').addEventListener('click',()=>mostrarPasso(passo+1));
calcular();atualizarEstimativa();mostrarPasso(1);if(document.getElementById('cliente').value)document.getElementById('cliente').dispatchEvent(new Event('change'));
</script>
